digits = range(1, 10)

for a in digits:
    for b in digits:
        if a == b:
            continue

        m = 10 * a + b

        is_good = False
        conditions = []

        # Case 1: Removing 'a' leaves 'b'. b must divide m.
        # Since b is a single digit, it is good.
        if m % b == 0:
            is_good = True
            conditions.append(f"Removing '{a}' leaves {b}. {b} divides {m}.")

        # Case 2: Removing 'b' leaves 'a'. a must divide m.
        # Since a is a single digit, it is good.
        if m % a == 0:
            is_good = True
            conditions.append(f"Removing '{b}' leaves {a}. {a} divides {m}.")

        if is_good:
            good_numbers[m] = conditions

# Sort by the number itself to easily find the largest
sorted_good_numbers = sorted(good_numbers.keys())
largest_good_number = max(sorted_good_numbers) if sorted_good_numbers else None

print("--- 2-Digit Good Numbers ---")
for m, cond in good_numbers.items():
    print(f"m = {m} (a={m//10}, b={m%10}):")
    for c in cond:
        print(f"  - {c}")

print("\n--- Summary ---")
print(f"Total good numbers found: {len(good_numbers)}")
if largest_good_number is not None:
    print(f"Largest good number found: {largest_good_number}")
